out.append('''*{box-sizing:border-box}:root{--bg:#000;--text:#f2f2f2;--border:#3a3a3a;--mono:ui-monospace,Consolas,monospace;--sans:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}html{scroll-behavior:smooth}body{margin:0;background:#000;color:#eaeaea;font:17px/1.7 var(--sans)}.wrap{max-width:1060px;margin:auto;padding:64px 28px}h1{font-size:40px;line-height:1.12;font-weight:600;letter-spacing:-.02em;background:linear-gradient(#fff,#aaa);background-clip:text;-webkit-text-fill-color:transparent}h2{font:600 13px var(--mono);letter-spacing:.22em;text-transform:uppercase;color:#b4b4b4;border-bottom:1px solid #333;padding-bottom:16px;margin-top:64px}h3{font-size:20px;font-weight:600;letter-spacing:-.01em}.eyebrow{font:12px var(--mono);letter-spacing:.28em;color:#b4b4b4}.meta,.tag{font:12px var(--mono);color:#b4b4b4}.lede{font-size:20px;border-left:3px solid #777;padding-left:18px;color:#dadada}.callout,article{border:1px solid #444;border-radius:10px;padding:20px;margin:24px 0;background:#0a0a0a}article:target{border-color:#fff}a{color:#fff}button{font:13px var(--mono);background:#111;color:#fff;border:1px solid #666;border-radius:7px;padding:10px;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #fff;outline-offset:3px}button:disabled{opacity:.45;cursor:default}.track{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.node.active{background:#eee;color:#000;border-color:#fff}.detail{border:1px solid #555;padding:16px;margin:16px 0;font-size:17px}.nav{display:flex;gap:14px;align-items:center}.counter{font:13px var(--mono)}.toc{display:none;position:fixed;inset:0 auto 0 0;width:240px;padding:64px 22px;background:#000;border-right:1px solid #333}.toc a{display:block;font:13px/1.6 var(--mono);padding:10px 0;color:#b4b4b4;text-decoration:none}.toc a.active{color:#fff}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:12px;border:1px solid #444;vertical-align:top}th{font:11px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:#b4b4b4}td{font-size:17px;overflow-wrap:anywhere}.scroll{overflow:auto}.result{border-left:3px solid #bbb;padding-left:16px}footer{font:12px var(--mono);color:#b4b4b4;text-align:center;margin-top:50px}@media(min-width:1181px){body{padding-left:240px}.toc{display:block}}@media(max-width:680px){h1{font-size:30px}.wrap{padding:32px 18px}}@media print{body{background:white;color:black;padding:0}.toc,button,.track,.nav{display:none}.wrap{max-width:none;padding:0}h1{-webkit-text-fill-color:black}article,.callout{background:white;color:black;break-inside:avoid}a,h2,.meta,.tag,.eyebrow{color:black}.detail{display:none}.printsteps{display:block!important}section{break-before:auto}}.printsteps{display:none}''')
out.append('</style></head><body><nav class="toc" aria-label="Contents">'+''.join(f'<a href="#{i}" data-toc="{i}">{n:02} {esc(t)}</a>' for n,(i,t) in enumerate(sections,1))+'</nav><main class="wrap">')
out.append(f'<header><p class="eyebrow">NISM SYNC / QUALITY ASSURANCE</p><h1>Enrollment Dashboard<br>Test Cases</h1><p class="meta">TASK #58204 · VERSION 0.1 · 15 OCTOBER 2026 · {len(cases)} CASES</p><p class="lede">Concrete manual test specification derived from draft PRD #58203 v0.1. Every case is Not run. Business rules and targets remain proposed until approved.</p></header>')
out.append('<section id="s01"><h2>01 Scope and approval</h2><p>Original work item title: Create Test Cases for Enrollment Dashboard. Revision 1 had no description or acceptance criteria. Confirmed feature scope from #58203 is enrollment trends, exam distribution, profile review controls and upcoming sessions with seat availability. Detailed expectations here trace to a proposed PRD, not approved business rules.</p><p>Priority P0: access control, decision integrity, reconciliation, core correctness and recovery. P1: other acceptance coverage and usability. Review priorities with product and QA.</p><div class="callout"><p>No application, backend, API, load or accessibility tests were executed. This deliverable completes test design only. No Azure Test Plans suite or individual test-case work items were created.</p></div><ul>')
out.extend(f'<li><strong>{g}</strong>: {esc(v)}</li>' for g,v in gates.items())
out.append('</ul><p>Out of scope: payment/refund processing, enrollment creation, capacity editing, session scheduling, exam delivery, bulk profile approval and export. Booking-path verification is an integration dependency, not a new dashboard booking feature.</p></section><section id="s02"><h2>02 Fixtures and oracle</h2>')
out.extend(f'<h3>{esc(k)}</h3><p>{esc(v)}</p>' for k,v in fixtures)
out.append('</section><section id="s03"><h2>03 Test cases</h2><p>Select numbered step nodes or use Back/Next. Left/Right arrows work when the case walkthrough has focus. The entire procedure remains available when printing.</p>')
for c in cases:
    out.append(f'<article id="{c["id"]}"><h3>{c["id"]}: {esc(c["title"])}</h3><p class="meta">{c["priority"]} · {" / ".join(c["requirements"])} · {" / ".join(c["acceptance"])} · NOT RUN</p><p><strong>Preconditions/data:</strong> {esc(c["preconditions"])}</p><p><strong>Approval gate:</strong> {esc(c["approval_gate"])}</p><div class="walk" tabindex="0" aria-label="{c["id"]} procedure"><div class="track">')
    out.extend(f'<button type="button" class="node" data-i="{i}">Step {i+1}</button>' for i in range(len(c['steps'])))
    out.append('</div><div class="detail" aria-live="polite"></div><div class="nav"><button type="button" class="prev">Back</button><span class="counter"></span><button type="button" class="next">Next</button></div>')
    out.append('<ol class="printsteps">'+''.join(f'<li>{esc(s)}</li>' for s in c['steps'])+'</ol></div>')
    out.append(f'<p class="result"><strong>Expected outcome:</strong> {esc(c["expected"])}</p><p class="tag">ACTUAL RESULT / EVIDENCE: NOT RECORDED</p></article>')
out.append('</section><section id="s04"><h2>04 Traceability</h2><div class="scroll"><table><thead><tr><th scope="col">Requirement / acceptance</th><th scope="col">Test cases</th></tr></thead><tbody>')
out.extend('<tr><th scope="row">'+k+'</th><td>'+', '.join(f'<a href="#{v}">{v}</a>' for v in values)+'</td></tr>' for k,values in trace.items())
out.append('</tbody></table></div></section><section id="s05"><h2>05 Execution and exit</h2><p>Execution entry: approved PRD and G1–G7 decisions, deployed identifiable build, role-mapped test users, seeded synthetic data, test adapters and safe audit verification. Block individual cases where their business gate or dependency is unresolved; do not silently convert a proposal into an acceptance rule.</p><p>For each run, record case ID, build/environment, date, tester, browser/assistive technology, actual result, pass/fail/blocked, evidence link and defect ID. Restore fixture after mutations; performance runs need their own agreed workload and sample size. Sanitise screenshots and logs.</p><p>Proposed release exit: approved scope and business rules, every P0 passes, remaining defects explicitly triaged by owner, access and concurrency checks pass, approved freshness/performance/accessibility targets met. This is a recommendation, not a team commitment.</p><p><a href="https://dev.azure.com/schoolnetindia/NISM%20Sync/_workitems/edit/58203">Source PRD work item #58203</a> · <a href="https://dev.azure.com/schoolnetindia/NISM%20Sync/_workitems/edit/58204">Test design work item #58204</a> · <a href="../test_cases.json">Structured test specification JSON</a></p></section><footer>enrollment-dashboard-tests.html · Self-contained OLED monochrome document</footer></main><script>')
data=json.dumps([c['steps'] for c in cases], ensure_ascii=False).replace('<','\\u003c')
out.append('const steps='+data+''';document.querySelectorAll('.walk').forEach((walk,index)=>{let i=0;const nodes=walk.querySelectorAll('.node'),prev=walk.querySelector('.prev'),next=walk.querySelector('.next');function render(){nodes.forEach((n,j)=>{n.classList.toggle('active',i===j);n.setAttribute('aria-pressed',String(i===j));});walk.querySelector('.detail').textContent=steps[index][i];walk.querySelector('.counter').textContent=(i+1)+' / '+nodes.length;prev.disabled=i===0;next.disabled=i===nodes.length-1;}nodes.forEach((n,j)=>n.addEventListener('click',()=>{i=j;render()}));prev.addEventListener('click',()=>{if(i>0)i--;render()});next.addEventListener('click',()=>{if(i<nodes.length-1)i++;render()});walk.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();i=Math.max(0,Math.min(nodes.length-1,i+(e.key==='ArrowRight'?1:-1)));render()}});render()});const links=[...document.querySelectorAll('[data-toc]')];if('IntersectionObserver'in window){const obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)links.forEach(a=>a.classList.toggle('active',a.dataset.toc===e.target.id))})},{rootMargin:'-20% 0px -70% 0px'});document.querySelectorAll('section[id]').forEach(s=>obs.observe(s))}''')
out.append('</script></body></html>')
ROOT.joinpath('docs/enrollment-dashboard-tests.html').write_text(''.join(out),encoding='utf-8')
print(f'Generated {len(cases)} cases, covering {len(trace)} requirement/acceptance IDs; every case Not run.')
